def backfill_comment_threads(apps, schema_editor):
    alias = schema_editor.connection.alias
    comment = apps.get_model("db", "IssueComment")
    thread = apps.get_model("lab", "ChatThread")
    baseline = django.utils.timezone.now()
    rows = (
        comment.objects.using(alias)
        .filter(deleted_at__isnull=True, issue__deleted_at__isnull=True)
        .values("workspace_id", "project_id", "issue_id")
        .annotate(latest=models.Max("created_at"))
    )
    batch = []
    for row in rows.iterator(chunk_size=1000):
        batch.append(
            thread(
                workspace_id=row["workspace_id"],
                project_id=row["project_id"],
                issue_id=row["issue_id"],
                scope="issue",
                baseline_at=baseline,
                activity_at=row["latest"],
            )
        )
        if len(batch) == 1000:
            thread.objects.using(alias).bulk_create(batch, ignore_conflicts=True)
            batch = []
    thread.objects.using(alias).bulk_create(batch, ignore_conflicts=True)


